/* @autogenerated */
package net.civeira.phylax.feature.observe.probe;

import java.io.IOException;
import java.net.InetAddress;
import java.net.URI;
import java.net.UnknownHostException;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.security.cert.Certificate;
import java.security.cert.X509Certificate;
import java.time.Duration;
import java.util.Locale;
import java.util.Set;

/**
 * One HTTP check of a probe, without framework: the result says whether it is UP, how long it took
 * and why it failed. Only http(s) URLs of the allowed hosts are called (a probe must not become a
 * way to reach the internal network), never local or link-local addresses (cloud metadata), and
 * redirects are not followed.
 */
public final class ProbeCheck {

  /** What a probe asks. */
  public record Target(String url, String method, int expectedStatus, String expectedText,
      int timeoutMs) {}

  /**
   * @param tlsExpiresAt epoch millis of the expiration of the certificate (https), or null
   */
  public record Result(boolean up, long latencyMs, String error, Long tlsExpiresAt) {}

  private ProbeCheck() {}

  /** Why the host of the URL cannot be called, or null if it can. */
  public static String forbidden(final String url, final Set<String> allowedHosts) {
    URI uri;
    try {
      uri = URI.create(url.trim());
    } catch (IllegalArgumentException ex) {
      return "invalid URL";
    }
    String scheme = null == uri.getScheme() ? "" : uri.getScheme().toLowerCase(Locale.ROOT);
    if (!"http".equals(scheme) && !"https".equals(scheme)) {
      return "only http and https URLs";
    }
    String host = null == uri.getHost() ? "" : uri.getHost().toLowerCase(Locale.ROOT);
    if (host.isEmpty()) {
      return "URL without host";
    }
    if (!allowedHosts.contains(host)) {
      return "host " + host + " not allowed (app.observe.probes.allowed-hosts)";
    }
    try {
      for (InetAddress address : InetAddress.getAllByName(host)) {
        if (address.isLinkLocalAddress() || address.isAnyLocalAddress()
            || address.isMulticastAddress()) {
          return "address " + address.getHostAddress() + " not allowed";
        }
      }
    } catch (UnknownHostException ex) {
      return "unknown host " + host;
    }
    return null;
  }

  public static Result run(final HttpClient http, final Target target,
      final Set<String> allowedHosts) {
    String forbidden = forbidden(target.url(), allowedHosts);
    if (null != forbidden) {
      return new Result(false, 0, forbidden, null);
    }
    long started = System.nanoTime();
    try {
      HttpRequest.Builder request = HttpRequest.newBuilder(URI.create(target.url().trim()))
          .timeout(Duration.ofMillis(Math.max(500, target.timeoutMs())))
          .header("User-Agent", "observe-probe");
      String method = null == target.method() ? "GET" : target.method().toUpperCase(Locale.ROOT);
      request = switch (method) {
        case "HEAD" -> request.method("HEAD", HttpRequest.BodyPublishers.noBody());
        case "POST" -> request.POST(HttpRequest.BodyPublishers.noBody());
        default -> request.GET();
      };
      HttpResponse<String> response =
          http.send(request.build(), HttpResponse.BodyHandlers.ofString());
      long latency = (System.nanoTime() - started) / 1_000_000;
      Long tls = response.sslSession().map(session -> {
        try {
          Certificate[] certificates = session.getPeerCertificates();
          return certificates.length > 0 && certificates[0] instanceof X509Certificate x509
              ? x509.getNotAfter().getTime()
              : null;
        } catch (javax.net.ssl.SSLPeerUnverifiedException ex) {
          return null;
        }
      }).orElse(null);
      if (response.statusCode() != target.expectedStatus()) {
        return new Result(false, latency,
            "status " + response.statusCode() + ", expected " + target.expectedStatus(), tls);
      }
      if (null != target.expectedText() && !target.expectedText().isBlank()
          && (null == response.body() || !response.body().contains(target.expectedText()))) {
        return new Result(false, latency, "expected text not found", tls);
      }
      return new Result(true, latency, null, tls);
    } catch (java.net.http.HttpTimeoutException ex) {
      return new Result(false, (System.nanoTime() - started) / 1_000_000, "timeout", null);
    } catch (IOException ex) {
      return new Result(false, (System.nanoTime() - started) / 1_000_000,
          ex.getClass().getSimpleName() + (null == ex.getMessage() ? "" : ": " + ex.getMessage()),
          null);
    } catch (InterruptedException ex) {
      Thread.currentThread().interrupt();
      return new Result(false, 0, "interrupted", null);
    } catch (IllegalArgumentException ex) {
      return new Result(false, 0, "invalid request: " + ex.getMessage(), null);
    }
  }
}
